1	import React, { useState, useEffect } from 'react';
2	import { Link, useParams } from 'react-router-dom';
3	import { FiChevronLeft, FiChevronRight } from 'react-icons/fi';
4	
5	import api from '../../services/api';
6	
7	import logoImage from '../../assets/logo.svg';
8	import Footer from '../../components/Footer';
9	
10	import { Header, RespositoryInfo, Tabs, Issues } from './styles';
11	
12	interface Repository {
13	  full_name: string;
14	  description: string;
15	  owner: {
16	    login: string;
17	    avatar_url: string;
18	  };
19	  stargazers_count: number;
20	  forks_count: number;
21	  open_issues_count: number;
22	}
23	interface Issue {
24	  id: number;
25	  title: string;
26	  html_url: string;
27	  user: {
28	    login: string;
29	  };
30	}
31	interface PullRequest {
32	  id: number;
33	  title: string;
34	  html_url: string;
35	  created_at: string;
36	  user: {
37	    login: string;
38	  };
39	}
40	
41	type Tab = 'issues' | 'pullRequests';
42	
43	const Repository: React.FC = () => {
44	  const { '*': repositoryName } = useParams();
45	  const [repository, setRepository] = useState<Repository | null>(null);
46	  const [issues, setIssues] = useState<Issue[]>([]);
47	  const [pullRequests, setPullRequests] = useState<PullRequest[]>([]);
48	  const [activeTab, setActiveTab] = useState<Tab>('issues');
49	
50	  useEffect(() => {
51	    api.get(`/repos/${repositoryName}`).then((response) => {
52	      setRepository(response.data);
53	    });
54	    api.get(`/repos/${repositoryName}/issues`).then((response) => {
55	      setIssues(response.data);
56	    });
57	    api.get(`/repos/${repositoryName}/pulls`, { params: { state: 'open' } }).then((response) => {
58	      setPullRequests(response.data);
59	    });
60	  }, [repositoryName]);
61	
62	  return (
63	    <>
64	      <Header>
65	        <img src={logoImage} alt="Github Explorer" />
66	        <Link to="/">
67	          <FiChevronLeft size={16} color="#3D3D4D" />
68	          <strong>Voltar</strong>
69	        </Link>
70	      </Header>
71	      {repository ? (
72	        <RespositoryInfo>
73	          <header>
74	            <img src={repository.owner.avatar_url} alt="Owner profile avatar" />
75	            <div>
76	              <strong>{repository.full_name}</strong>
77	              <p>{repository.description}</p>
78	            </div>
79	          </header>
80	          <ul>
81	            <li>
82	              <strong>{repository.stargazers_count}</strong>
83	              <span>Stars</span>
84	            </li>
85	            <li>
86	              <strong>{repository.forks_count}</strong>
87	              <span>Forks</span>
88	            </li>
89	            <li>
90	              <strong>{repository.open_issues_count}</strong>
91	              <span>Issues abertos</span>
92	            </li>
93	          </ul>
94	        </RespositoryInfo>
95	      ) : (
96	        <p>Carregando informações.</p>
97	      )}
98	
99	      <Tabs>
100	        <button
101	          type="button"
102	          className={activeTab === 'issues' ? 'active' : ''}
103	          onClick={() => setActiveTab('issues')}
104	        >
105	          Issues
106	        </button>
107	        <button
108	          type="button"
109	          className={activeTab === 'pullRequests' ? 'active' : ''}
110	          onClick={() => setActiveTab('pullRequests')}
111	        >
112	          Pull Requests
113	        </button>
114	      </Tabs>
115	
116	      {activeTab === 'issues' ? (
117	        <Issues>
118	          {issues.map((issue) => (
119	            <a key={issue.id} href={issue.html_url}>
120	              <div>
121	                <strong>{issue.title}</strong>
122	                <p>{issue.user.login}</p>
123	              </div>
124	              <FiChevronRight size={20} />
125	            </a>
126	          ))}
127	        </Issues>
128	      ) : (
129	        <Issues>
130	          {pullRequests.map((pullRequest) => (
131	            <a key={pullRequest.id} href={pullRequest.html_url}>
132	              <div>
133	                <strong>{pullRequest.title}</strong>
134	                <p>
135	                  {pullRequest.user.login} · {new Date(pullRequest.created_at).toLocaleDateString('pt-BR')}
136	                </p>
137	              </div>
138	              <FiChevronRight size={20} />
139	            </a>
140	          ))}
141	        </Issues>
142	      )}
143	
144	      <Footer />
145	    </>
146	  );
147	};
148	
149	export default Repository;
